// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // bound _owner to a non-zero address to avoid admin collision
        vm.assume(_owner != address(0));
        vm.assume(_owner != address(this)); // admin is contract deployer

        c.setOwner(_owner);

        assertTrue(c.owner() == _owner);
    }
}

